PaymentCardLabelParts.definition:
type PaymentCardLabelParts = {
  /** The brand, when `brand` is text; otherwise undefined. */
  brand?: string;
  /** The holder's name. */
  holderName: string;
  /** The last four digits. */
  last4: string;
  /** The tier, when `label` is given. */
  label?: string;
};
